def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    row_cells: list[list[tuple[int, str]]] = [[] for _ in range(100)]
    for name in cells:
        col = ord(name[0]) - 65
        row = int(name[1:])
        row_cells[row].append((col, name))
    for r in range(1, 100):
        if row_cells[r]:
            row_cells[r].sort()

    def tokenize(s: str) -> list[tuple[str, str]]:
        tokens: list[tuple[str, str]] = []
        i = 0
        n = len(s)
        while i < n:
            ch = s[i]
            if ch.isspace():
                i += 1
            elif ch.isdigit():
                j = i + 1
                while j < n and s[j].isdigit():
                    j += 1
                tokens.append(("NUM", s[i:j]))
                i = j
            elif ch.isalpha():
                j = i + 1
                while j < n and s[j].isalnum():
                    j += 1
                tokens.append(("ID", s[i:j]))
                i = j
            elif ch == "<" and i + 1 < n and s[i + 1] in (">", "="):
                tokens.append(("OP", s[i : i + 2]))
                i += 2
            elif ch == ">" and i + 1 < n and s[i + 1] == "=":
                tokens.append(("OP", ">="))
                i += 2
            else:
                tokens.append(("OP", ch))
                i += 1
        tokens.append(("EOF", ""))
        return tokens

    def parse_formula(s: str) -> tuple:
        tokens = tokenize(s)
        pos = 0

        def parse_expr() -> tuple:
            nonlocal pos
            node = parse_term()
            while tokens[pos][0] == "OP" and tokens[pos][1] in ("+", "-"):
                op = tokens[pos][1]
                pos += 1
                right = parse_term()
                node = ("bin", op, node, right)
            return node

        def parse_term() -> tuple:
            nonlocal pos
            node = parse_unary()
            while tokens[pos][0] == "OP" and tokens[pos][1] in ("*", "/"):
                op = tokens[pos][1]
                pos += 1
                right = parse_unary()
                node = ("bin", op, node, right)
            return node

        def parse_unary() -> tuple:
            nonlocal pos
            neg_count = 0
            while tokens[pos][0] == "OP" and tokens[pos][1] == "-":
                neg_count += 1
                pos += 1
            node = parse_atom()
            if neg_count & 1:
                node = ("neg", node)
            return node

        def parse_atom() -> tuple:
            nonlocal pos
            kind, text = tokens[pos]
            if kind == "NUM":
                pos += 1
                return ("num", int(text))
            if kind == "OP" and text == "(":
                pos += 1
                node = parse_expr()
                pos += 1  # consume ')'
                return node
            pos += 1
            if text == "IF":
                pos += 1  # consume '('
                left = parse_expr()
                op = tokens[pos][1]
                pos += 1
                right = parse_expr()
                pos += 1  # consume ','
                then_expr = parse_expr()
                pos += 1  # consume ','
                else_expr = parse_expr()
                pos += 1  # consume ')'
                return ("if", op, left, right, then_expr, else_expr)
            if text in ("SUM", "MIN", "MAX"):
                pos += 1  # consume '('
                items: list[tuple] = []
                while True:
                    if tokens[pos][0] == "ID" and tokens[pos + 1] == ("OP", ":"):
                        c1_name = tokens[pos][1]
                        c2_name = tokens[pos + 2][1]
                        pos += 3
                        c1, r1 = ord(c1_name[0]) - 65, int(c1_name[1:])
                        c2, r2 = ord(c2_name[0]) - 65, int(c2_name[1:])
                        if c1 > c2:
                            c1, c2 = c2, c1
                        if r1 > r2:
                            r1, r2 = r2, r1
                        for r in range(r1, r2 + 1):
                            for c, cname in row_cells[r]:
                                if c1 <= c <= c2:
                                    items.append(("cell", cname))
                    else:
                        items.append(parse_expr())
                    if tokens[pos] == ("OP", ","):
                        pos += 1
                    else:
                        break
                pos += 1  # consume ')'
                return ("agg", text, items)
            return ("cell", text)

        return parse_expr()

    values: dict[str, int | str] = {}
    in_progress: set[str] = set()

    def eval_cell(start_name: str) -> None:
        stack: list[tuple] = []
        expr: tuple | None = ("cell", start_name)
        val: int | str = 0
        while True:
            if expr is not None:
                tag = expr[0]
                if tag == "num":
                    val = expr[1]
                    expr = None
                elif tag == "cell":
                    cname = expr[1]
                    if cname in values:
                        val = values[cname]
                        expr = None
                    elif cname not in cells:
                        val = 0
                        expr = None
                    elif cname in in_progress:
                        val = "#CYCLE!"
                        expr = None
                    else:
                        raw = cells[cname].strip()
                        if not raw.startswith("="):
                            val = int(raw)
                            values[cname] = val
                            expr = None
                        else:
                            in_progress.add(cname)
                            stack.append(("cell_done", cname))
                            expr = parse_formula(raw[1:])
                elif tag == "neg":
                    stack.append(("neg",))
                    expr = expr[1]
                elif tag == "bin":
                    stack.append(("bin_l", expr[1], expr[3]))
                    expr = expr[2]
                elif tag == "if":
                    stack.append(("if_l", expr[1], expr[3], expr[4], expr[5]))
                    expr = expr[2]
                else:  # "agg"
                    items = expr[2]
                    if not items:
                        val = 0
                        expr = None
                    else:
                        stack.append(("agg", expr[1], items, 1, None))
                        expr = items[0]
            else:
                if not stack:
                    return
                frame = stack.pop()
                ftag = frame[0]
                if ftag == "cell_done":
                    cname = frame[1]
                    in_progress.remove(cname)
                    values[cname] = val
                elif ftag == "neg":
                    if isinstance(val, int):
                        val = -val
                elif ftag == "bin_l":
                    if isinstance(val, int):
                        stack.append(("bin_r", frame[1], val))
                        expr = frame[2]
                elif ftag == "bin_r":
                    if isinstance(val, int):
                        op = frame[1]
                        left_val = frame[2]
                        if op == "+":
                            val = left_val + val
                        elif op == "-":
                            val = left_val - val
                        elif op == "*":
                            val = left_val * val
                        else:
                            if val == 0:
                                val = "#DIV/0!"
                            else:
                                q = abs(left_val) // abs(val)
                                val = -q if (left_val < 0) ^ (val < 0) else q
                elif ftag == "if_l":
                    if isinstance(val, int):
                        stack.append(("if_r", frame[1], val, frame[3], frame[4]))
                        expr = frame[2]
                elif ftag == "if_r":
                    if isinstance(val, int):
                        op = frame[1]
                        left_val = frame[2]
                        if op == "=":
                            cond = left_val == val
                        elif op == "<>":
                            cond = left_val != val
                        elif op == "<":
                            cond = left_val < val
                        elif op == "<=":
                            cond = left_val <= val
                        elif op == ">":
                            cond = left_val > val
                        else:
                            cond = left_val >= val
                        expr = frame[3] if cond else frame[4]
                else:  # "agg"
                    if isinstance(val, int):
                        func_name, items, idx, acc = frame[1], frame[2], frame[3], frame[4]
                        if func_name == "SUM":
                            acc = val if acc is None else acc + val
                        elif func_name == "MIN":
                            acc = val if acc is None or val < acc else acc
                        else:
                            acc = val if acc is None or val > acc else acc
                        if idx < len(items):
                            stack.append(("agg", func_name, items, idx + 1, acc))
                            expr = items[idx]
                        else:
                            val = 0 if acc is None else acc

    for name in cells:
        if name not in values:
            eval_cell(name)
    return values
